// Gabarit e-mail commun « lagon » : fond clair, carte blanche à bordure fine, mot-symbole bicolore. Aucun émoji.
const escape = (value) =>
  String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

